-- opnview — deterministic seed for the schema checks.
--
-- Pure SQL, generated by recursive common table expressions. No Go code, no
-- external generator, and no address literal: every address is synthesised
-- from a counter at generation time and carries no addressing-plan meaning.
-- Nothing in the schema or in the seven screen queries interprets an address;
-- interface membership is carried by foreign keys, never by an address range.
--
-- Bound parameters, all supplied by the caller. The row counts are parameters
-- precisely so the checks can re-run the whole file against a different number
-- of interfaces, clients and flows and show that nothing assumes the defaults.
--
--   :now          the instant the seed pretends to run, UTC epoch seconds
--   :interfaces     how many interfaces to discover        (must be >= 2)
--   :clients      how many clients to observe          (must be > :interfaces)
--   :rules        how many firewall rules to discover  (must be >= 2)
--   :owners       how many owners the user has created (must be >= 1)
--   :flow_rows    rows in flow, the largest growing table
--   :alerts       rows in security_event
--   :pair_rows    logical pairs in pair_volume_observation; each one is
--                 offered twice, once per direction, and must collapse to one
--   :ipv6_every   every Nth slot of the address pool below is IPv6 rather than
--                 IPv4 (must be >= 2). It is a PARAMETER and not a proportion
--                 written into this file, for the same reason the counts are:
--                 the checks re-run the whole seed with a different value, so
--                 nothing may assume how much of a network is v6 -- and because
--                 it changes which FAMILY a row carries and never HOW MANY rows
--                 exist, the row counts and their determinism comparisons stay
--                 legible against the counts above.
--
-- Running the file twice against the same fresh database produces identical
-- row counts per table.


BEGIN;

-- ---------------------------------------------------------------------------
-- The address pool: one row per numbered slot, carrying that slot's address in
-- both families.
--
-- WHY BOTH FAMILIES PER SLOT rather than one family per slot: a filter-log
-- record reports a single ipversion, so both of its endpoints are of one family.
-- Holding both addresses for every slot lets a generated flow pick its family
-- and then take both endpoints from that family, which is what a real record
-- looks like. A client, meanwhile, carries ONE last_address, and a dual-stack
-- machine really does appear in flows of both families -- so the client's own
-- family and its flows' families are decided separately and deliberately.
--
-- NEITHER ADDRESS IS A LITERAL. Both are synthesised from the slot number, and
-- neither carries any addressing-plan meaning: nothing in the schema or in the
-- seven screen queries interprets an address, and interface membership is
-- carried by foreign keys. The IPv6 form is eight hexadecimal groups derived
-- from the slot, deliberately NOT a documentation prefix, because a recognisable
-- prefix would be a literal about somebody's addressing.
--
-- It is a TEMP table, so it lives for this connection only and appears in no
-- entity list: it is a generator, not part of the model.
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE synth_address (
    slot       INTEGER PRIMARY KEY,
    address_v4 TEXT NOT NULL,
    address_v6 TEXT NOT NULL
);

WITH RECURSIVE local_slot (slot) AS (
    SELECT 1
    UNION ALL
    SELECT slot + 1 FROM local_slot WHERE slot < :clients + 3
),
external_slot (slot) AS (
    SELECT 1000000
    UNION ALL
    SELECT slot + 1 FROM external_slot
    WHERE slot < 1000000 + greatest(3999, :pair_rows)
),
-- One slot per interface address and per gateway: 900000 + n is interface n's own
-- address, 950000 + n the gateway behind the upstream interface, and 960000 + n the
-- address the upstream interface held before its current one.
interface_slot (slot) AS (
    SELECT 900001
    UNION ALL
    SELECT slot + 1 FROM interface_slot WHERE slot < 900000 + :interfaces + 1
),
every_slot (slot) AS (
    SELECT slot FROM local_slot
    UNION
    SELECT slot FROM external_slot
    UNION
    SELECT slot FROM interface_slot
    UNION
    SELECT 950000 + :interfaces + 1
    UNION
    SELECT 960000 + :interfaces + 1
)
INSERT INTO synth_address (slot, address_v4, address_v6)
SELECT
    slot,
    format('%s.%s.%s.%s',
           (slot / 16777216) % 256, (slot / 65536) % 256, (slot / 256) % 256, slot % 256),
    concat_ws(':',
              to_hex((slot * 7) % 65536), to_hex((slot * 11) % 65536), to_hex((slot * 13) % 65536),
              to_hex((slot * 17) % 65536), to_hex((slot * 19) % 65536), to_hex((slot * 23) % 65536),
              to_hex((slot * 29) % 65536), to_hex(slot % 65536))
FROM every_slot;

-- ---------------------------------------------------------------------------
-- The provider registry already holds one row per surveyed implementation, with
-- none active. A probe round has now run, so the seed marks the providers this
-- pretend-installation reads.
--
-- ONE PER EXCLUSIVE KIND, AND THAT IS THE RULE RATHER THAN A HABIT. The partial
-- unique index rejects a second active provider of a kind whose destination rows
-- do not carry their provider; it deliberately does not govern security_event,
-- dhcp_lease, measurement_sample or reconciled_state, where two active providers
-- are two attributed sets of rows rather than one doubled figure.
--
-- THIS INSTALLATION RUNS TWO DHCP SERVERS, because that is the deployment the
-- concurrency was decided for: one issuing on one VLAN and another on a second,
-- two scopes with no overlap. Both are active, both contribute leases below, and
-- one machine is leased by both -- which is ONE client holding TWO leases, because
-- the identity cascade keys on the DHCP client identifier and then on the MAC,
-- neither of them scoped to an interface. The concurrent security_event case is
-- exercised where a second implementation is registered, further down in
-- sql/schema-checks.sh.
--
-- flow_volume is NOT activated, and that is the ruling rather than an omission:
-- pair_volume_observation is derived from flow by step 5, so nothing collects
-- that kind and nothing probes it. Its rows below are seeded directly, as the
-- derivation would write them.
--
-- Everything below that needs a provider looks it up by kind and activeness,
-- never by name, with ONE deliberate exception: the lease blocks name the two DHCP
-- servers by key, because the whole point of this installation is that two of them
-- are running and every lease row has to say which one issued it. Naming them is
-- what the fixture is FOR; nothing in the schema, in a query or in an index tests
-- those strings.
-- ---------------------------------------------------------------------------
-- A source of the reconciled_state kind. The schema registers none -- a registry
-- row is a claim that an implementation exists, and no connector for a
-- state-shaped source is written yet -- so this pretend-installation registers
-- the one it pretends to run, which is the INSERT such a connector's cycle would
-- add. The name is an example value in a fixture and matches no product.
INSERT INTO provider (kind, provider_key, display_name, is_active, registered_at)
VALUES ('reconciled_state', 'example-state-source', 'Example state source', 0, :now)
ON CONFLICT (kind, provider_key) DO NOTHING;

INSERT INTO source_availability (provider_id, state, probe, detail, checked_at)
SELECT p.id, 'unavailable', 'not_yet_probed', NULL, 0
FROM provider AS p
WHERE NOT EXISTS (SELECT 1 FROM source_availability a WHERE a.provider_id = p.id);

UPDATE provider SET is_active = true
WHERE (kind, provider_key) IN (
    VALUES ('firewall_log', 'pf'),
           ('security_event', 'suricata'),
           ('measurement_sample', 'insight'),
           ('dhcp_lease', 'kea'),
           ('dhcp_lease', 'dnsmasq'),
           ('dns_lookup', 'unbound'),
           ('ip_geolocation', 'maxmind_geolite2'),
           ('registrable_domain', 'public_suffix_list'),
           ('reconciled_state', 'example-state-source')
);

-- ---------------------------------------------------------------------------
-- Interfaces. The last one is discovered as a tunnel, every other as a VLAN, so
-- both kinds are present whatever :interfaces is. link_kind is derived from the
-- discovered link type and from nothing else: no name is inspected anywhere.
-- ---------------------------------------------------------------------------
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < :interfaces
),
discovered AS (
    SELECT
        n,
        CASE WHEN n = :interfaces THEN 'tunnel' ELSE 'vlan' END AS link_type
    FROM counter
)
INSERT INTO interface (id, identifier, device, description,
                     user_label, status, enabled, link_type, link_kind, vlan_tag,
                     address_family, first_seen_at, last_seen_at)
SELECT
    n,
    format('interface-identifier-%s', n),
    format('device-%s', n),
    format('discovered-description-%s', n),
    NULL,
    -- The link and administrative states, verbatim as the API reports them.
    -- Synthesised tokens, for the reason the descriptions above are: the
    -- survey establishes the two fields and not their encoding, so a token
    -- shaped like an OPNsense value would be asserting one. What the seed has
    -- to exercise is that an interface can carry a state other than the
    -- common one, and that an interface discovered without one reads as not
    -- reported rather than as switched off.
    CASE WHEN n % 5 = 0 THEN NULL
         WHEN n % 3 = 0 THEN 'link-state-alternative'
         ELSE 'link-state-primary' END,
    CASE WHEN n % 5 = 0 THEN NULL
         WHEN n % 4 = 0 THEN 'admin-state-alternative'
         ELSE 'admin-state-primary' END,
    link_type,
    CASE link_type
        WHEN 'tunnel' THEN 'tunnel'
        WHEN 'vlan' THEN 'vlan'
        ELSE 'other'
    END,
    100 + n,
    4,
    :now - 8640000,
    :now
FROM discovered;

-- One more interface, the UPSTREAM one: the response reported a gateway behind it.
-- No client sits behind it, because an address reached through it is outside; its
-- flows are the inbound ones below. It is identified by its position after the
-- others, never by a name.
INSERT INTO interface (id, identifier, device, description, user_label, status, enabled,
                       link_type, link_kind, vlan_tag, address_family, is_upstream,
                       first_seen_at, last_seen_at)
VALUES (:interfaces + 1, format('interface-identifier-%s', :interfaces + 1),
        format('device-%s', :interfaces + 1), format('discovered-description-%s', :interfaces + 1),
        NULL, 'link-state-primary', 'admin-state-primary', 'other', 'other', NULL, 4, 1,
        :now - 8640000, :now);

-- The interface map covers every discovered interface. Flows carrying a raw
-- device name absent from this table exercise the "not found" state.
INSERT INTO interface_map (device, description, interface_id, discovered_at)
SELECT device, description, id, :now - 8640000 FROM interface;

-- Every interface's own address in both families, from its slot of the pool, and the
-- gateway behind the upstream one. The upstream interface's IPv4 address CHANGED once,
-- so the table holds a history: the earlier address keeps the last instant it was seen.
INSERT INTO interface_address (interface_id, source_field, address, prefix_length,
                               address_family, first_seen_at, last_seen_at)
SELECT i.id, 'addr4', a.address_v4, 24, 4, :now - 8640000, :now
FROM interface AS i JOIN synth_address AS a ON a.slot = 900000 + i.id
UNION ALL
SELECT i.id, 'addr6', a.address_v6, 64, 6, :now - 8640000, :now
FROM interface AS i JOIN synth_address AS a ON a.slot = 900000 + i.id
UNION ALL
SELECT i.id, 'gateways', a.address_v4, NULL, 4, :now - 8640000, :now
FROM interface AS i JOIN synth_address AS a ON a.slot = 950000 + i.id
WHERE i.is_upstream
UNION ALL
SELECT i.id, 'gateways', a.address_v6, NULL, 6, :now - 8640000, :now
FROM interface AS i JOIN synth_address AS a ON a.slot = 950000 + i.id
WHERE i.is_upstream
UNION ALL
SELECT i.id, 'addr4', a.address_v4, 24, 4, :now - 17280000, :now - 8640001
FROM interface AS i JOIN synth_address AS a ON a.slot = 960000 + i.id
WHERE i.is_upstream;

-- The same addresses as `ipv4[]` and `ipv6[]` report them: every address an
-- interface holds, the primary one included, under the field's own name.
INSERT INTO interface_address (interface_id, source_field, address, prefix_length,
                               address_family, first_seen_at, last_seen_at)
SELECT interface_id, CASE source_field WHEN 'addr4' THEN 'ipv4' ELSE 'ipv6' END, address,
       prefix_length, address_family, first_seen_at, last_seen_at
FROM interface_address
WHERE source_field IN ('addr4', 'addr6') AND last_seen_at = :now;

-- The operator has said, on the first interface only, that a link-local address
-- seen there is membership evidence. Every other interface keeps the default, no.
UPDATE interface SET link_local_evidence = true WHERE id = 1;

-- The interface networks. Discovery proposed, for every interface, the network of
-- its IPv4 and IPv6 address: the address of its slot masked to the prefix length
-- written above, synthesised from the slot exactly as the address is. On top of
-- that the operator has added a narrower network to the first interface, and has
-- removed a network discovery once proposed for the second -- a removed detected
-- network that discovery must not bring back. Nothing here is a default: the
-- networks are fixture rows, as the addresses are.
INSERT INTO interface_network (interface_id, network_address, prefix_length, address_family,
                               origin, first_detected_at, last_detected_at, removed_at,
                               updated_at)
SELECT i.id,
       format('%s.%s.%s.0', (a.slot / 16777216) % 256, (a.slot / 65536) % 256, (a.slot / 256) % 256),
       24, 4, 'detected', :now - 8640000, :now, CAST(NULL AS BIGINT), :now
FROM interface AS i JOIN synth_address AS a ON a.slot = 900000 + i.id
UNION ALL
SELECT i.id,
       concat_ws(':', to_hex((a.slot * 7) % 65536), to_hex((a.slot * 11) % 65536),
                 to_hex((a.slot * 13) % 65536), to_hex((a.slot * 17) % 65536), '0', '0', '0', '0'),
       64, 6, 'detected', :now - 8640000, :now, NULL, :now
FROM interface AS i JOIN synth_address AS a ON a.slot = 900000 + i.id
UNION ALL
SELECT i.id,
       format('%s.%s.%s.0', (a.slot / 16777216) % 256, (a.slot / 65536) % 256, (a.slot / 256) % 256),
       25, 4, 'operator', CAST(NULL AS BIGINT), CAST(NULL AS BIGINT), CAST(NULL AS BIGINT), :now - 3600
FROM interface AS i JOIN synth_address AS a ON a.slot = 900000 + i.id
WHERE i.id = 1
UNION ALL
SELECT i.id,
       format('%s.%s.0.0', (a.slot / 16777216) % 256, (a.slot / 65536) % 256),
       16, 4, 'detected', :now - 17280000, :now - 8640001, :now - 7200, :now - 7200
FROM interface AS i JOIN synth_address AS a ON a.slot = 900000 + i.id
WHERE i.id = 2;

-- ---------------------------------------------------------------------------
-- Firewall rules.
-- ---------------------------------------------------------------------------
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < :rules
)
INSERT INTO rule (id, pf_label, description, action, direction, interface, legacy,
                  logs_matches, is_automatic, discovered_at, destination_net)
SELECT
    n,
    format('rule-label-%s', n),
    format('rule-description-%s', n),
    CASE WHEN n % 4 = 0 THEN 'block' ELSE 'pass' END,
    CASE WHEN n % 2 = 0 THEN 'in' ELSE 'out' END,
    -- The endpoint's `interface`, verbatim: one configuration key, two of them, the
    -- empty string of a floating rule, or -- on a legacy rule -- a description.
    CASE
        WHEN n % 6 = 5 THEN ''
        WHEN n % 5 = 0 THEN format('discovered-description-%s', ((n - 1) % :interfaces) + 1)
        WHEN n % 3 = 0 THEN format('interface-identifier-%s,interface-identifier-%s',
                                   ((n - 1) % :interfaces) + 1, (n % :interfaces) + 1)
        ELSE format('interface-identifier-%s', ((n - 1) % :interfaces) + 1)
    END,
    CASE WHEN n % 5 = 0 THEN 1 ELSE 0 END,
    -- All three states of the logging flag, because all three occur: a rule
    -- that logs, a rule that does not -- whose traffic opnview can never see,
    -- the second observation-point limit -- and a rule discovered from a
    -- source that did not report the flag at all.
    CASE WHEN n % 7 = 0 THEN 0 WHEN n % 11 = 0 THEN NULL ELSE 1 END,
    CASE WHEN n % 9 = 0 THEN 1 ELSE 0 END,
    :now - 8640000,
    -- The endpoint's `destination_net`, verbatim and never evaluated (B8a of
    -- specs/SPEC-step-5b-widget-api.md): `any`, an IPv4 and an IPv6 network from the
    -- synthesised pool, or not reported at all.
    CASE n % 4
        WHEN 0 THEN 'any'
        WHEN 1 THEN (SELECT a.address_v4 || '/32' FROM synth_address AS a WHERE a.slot = 1000000 + 500 + n)
        WHEN 2 THEN (SELECT a.address_v6 || '/128' FROM synth_address AS a WHERE a.slot = 1000000 + 500 + n)
    END
FROM counter;

-- ---------------------------------------------------------------------------
-- Owners. A row per person the user told opnview about. The firewall knows
-- nothing about any of them: ownership is entered in opnview and never
-- inferred, so these rows stand for user input and for nothing observed.
-- ---------------------------------------------------------------------------
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < :owners
)
INSERT INTO owner (id, display_name, created_at, updated_at)
SELECT n, format('owner-name-%s', n), :now - 8640000, :now - 86400
FROM counter;

-- ---------------------------------------------------------------------------
-- Clients.
--
-- The first octet of the MAC is 0x10 plus twice a counter modulo 8, so the
-- second hex digit walks 0, 2, 4, 6, 8, a, c, e. Four of those carry the IEEE
-- locally-administered bit (2, 6, a, e) and are randomised identities; the
-- other four (0, 4, 8, c) are globally administered burned-in addresses and
-- must NOT be marked unstable. Both halves are therefore present in every run.
--
-- Every tenth client has no MAC at all: the filter log carries none, so a
-- client seen only in flows must still be representable. Its identity falls to
-- the last level of the cascade, the address behind its interface over a
-- validity interval.
-- ---------------------------------------------------------------------------
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < :clients
),
generated AS (
    SELECT
        n,
        ((n - 1) % :interfaces) + 1 AS interface_id,
        CASE
            WHEN n % 10 = 0 THEN NULL
            ELSE concat_ws(':', lpad(to_hex(16 + (((n - 1) % 8) * 2)), 2, '0'),
                           lpad(to_hex((n * 7) % 256), 2, '0'), lpad(to_hex((n * 13) % 256), 2, '0'),
                           lpad(to_hex((n * 29) % 256), 2, '0'), lpad(to_hex((n * 37) % 256), 2, '0'),
                           lpad(to_hex(n % 256), 2, '0'))
        END AS mac,
        -- The client's own family. It is keyed on the client's POSITION WITHIN
        -- ITS INTERFACE rather than on its id, so every interface holds at least
        -- one IPv6 client whatever the interface count is -- an id-keyed rule
        -- aliases with the interface stride and can leave a whole interface
        -- single-family, which would make a per-interface screen untestable for
        -- one of the two.
        CASE WHEN ((n - 1) / :interfaces) % :ipv6_every = 0
             THEN a.address_v6 ELSE a.address_v4 END AS address
    FROM counter
    JOIN synth_address AS a ON a.slot = n
)
INSERT INTO client (id, identity_kind, identity_key, interface_id, mac, hostname,
                    vendor_hint, last_address, first_seen_at, last_seen_at)
SELECT
    n,
    CASE
        WHEN mac IS NULL THEN 'address_in_interface'
        WHEN n % 3 = 1 THEN 'dhcp_client_id'
        ELSE 'mac'
    END,
    CASE
        WHEN mac IS NULL THEN format('%s|%s|%s', interface_id, address, :now - 8640000)
        WHEN n % 3 = 1 THEN format('client-identity-%s', n)
        ELSE mac
    END,
    interface_id,
    mac,
    CASE WHEN mac IS NULL THEN NULL ELSE format('host-%s', n) END,
    format('vendor-hint-%s', n % 17),
    address,
    :now - 8640000,
    :now
FROM generated;

-- One address, reissued to a different machine after the first lease expired.
-- The two observations must stay two clients: the address level of the cascade
-- keys on the lease validity start, so the reissue produces a different
-- identity_key and nothing merges.
WITH reissued AS (
    SELECT format('%s.%s.%s.%s',
                  ((:clients + 1) / 16777216) % 256, ((:clients + 1) / 65536) % 256,
                  ((:clients + 1) / 256) % 256, (:clients + 1) % 256) AS address
)
INSERT INTO client (id, identity_kind, identity_key, interface_id, mac, hostname,
                    vendor_hint, last_address, first_seen_at, last_seen_at)
SELECT :clients + 1, 'address_in_interface',
       format('%s|%s|%s', 1, address, :now - 17280000),
       1, NULL, NULL, NULL, address, :now - 17280000, :now - 16416000
FROM reissued
UNION ALL
SELECT :clients + 2, 'address_in_interface',
       format('%s|%s|%s', 1, address, :now - 2592000),
       1, NULL, NULL, NULL, address, :now - 2592000, :now
FROM reissued;

-- The user has attributed every third client to an owner, and has left the
-- rest unattributed, which is the normal state of a network: ownership is
-- assigned by hand and is never derived from a hostname, a MAC prefix or a
-- vendor hint. Each owner ends up holding several machines, so the per-person
-- view has something to aggregate, and the majority of clients stay in the
-- unassigned bucket the diagnostic query has to keep visible.
--
-- The reissued pair above is deliberately left unowned: it exists to show two
-- identities behind one address, and attributing it would blur that.
UPDATE client
SET owner_id = (((id / 3) - 1) % :owners) + 1,
    owner_assigned_at = :now - 86400
WHERE id % 3 = 0 AND id <= :clients;

-- ---------------------------------------------------------------------------
-- DHCP leases. One per client that has a MAC, spread back over five months so
-- that a finite retention horizon has something to purge, plus the two leases
-- of the reissued address above.
--
-- BOTH BACKEND BEHAVIOURS APPEAR, because the model now distinguishes them. A
-- Kea lease carries a REAL validity start, `expire` minus `valid_lifetime`, and
-- its generation key rests on that start. A Dnsmasq lease carries NO start at
-- all -- the backend reports none, so the column is NULL rather than holding a
-- substitute -- and its generation key rests on the expiry, which is what keeps a
-- re-poll from inserting a second row. A standing reservation reports neither and
-- is keyed on the day it was observed.
-- ---------------------------------------------------------------------------
INSERT INTO dhcp_lease (provider_id, client_id, backend, address, mac, hostname,
                        dhcp_client_id, duid, iaid,
                        vendor_hint, lease_state, interface_id, starts_at, generation_key,
                        expires_at, observed_at)
SELECT
    (SELECT id FROM provider WHERE kind = 'dhcp_lease' AND provider_key = 'kea'),
    id,
    'kea',
    last_address,
    mac,
    hostname,
    CASE WHEN identity_kind = 'dhcp_client_id' THEN identity_key END,
    NULL,
    NULL,
    vendor_hint,
    'active',
    interface_id,
    :now - ((id % 8) * 1728000) - 3600,
    'start:' || (:now - ((id % 8) * 1728000) - 3600),
    :now - ((id % 8) * 1728000) + 86400,
    :now - ((id % 8) * 1728000)
FROM client
WHERE mac IS NOT NULL;

INSERT INTO dhcp_lease (provider_id, client_id, backend, address, mac, hostname,
                        dhcp_client_id, duid, iaid,
                        vendor_hint, lease_state, interface_id, starts_at, generation_key,
                        expires_at, observed_at)
SELECT (SELECT id FROM provider WHERE kind = 'dhcp_lease' AND provider_key = 'kea'), id, 'kea', last_address, NULL, NULL, NULL, NULL, NULL, NULL,
       'expired', interface_id, :now - 17280000, 'start:' || (:now - 17280000),
       :now - 16416000, :now - 16416000
FROM client WHERE id = :clients + 1
UNION ALL
SELECT (SELECT id FROM provider WHERE kind = 'dhcp_lease' AND provider_key = 'kea'), id, 'kea', last_address, NULL, NULL, NULL, NULL, NULL, NULL,
       'active', interface_id, :now - 2592000, 'start:' || (:now - 2592000),
       :now + 86400, :now
FROM client WHERE id = :clients + 2;

-- The Dnsmasq half: a backend that reports no validity start. Every one of these
-- rows carries a NULL start and a generation key resting on the expiry, and the
-- last one is a standing reservation, which reports neither and is keyed on the
-- day it was seen. They are spread over the same five months so the purge has
-- both something to remove and something to leave alone.
INSERT INTO dhcp_lease (provider_id, client_id, backend, address, mac, hostname,
                        dhcp_client_id, duid, iaid,
                        vendor_hint, lease_state, interface_id, starts_at, generation_key,
                        expires_at, observed_at)
SELECT
    (SELECT id FROM provider WHERE kind = 'dhcp_lease' AND provider_key = 'dnsmasq'),
    id,
    'dnsmasq',
    last_address,
    mac,
    hostname,
    NULL,
    NULL,
    NULL,
    vendor_hint,
    'active',
    interface_id,
    CAST(NULL AS BIGINT),
    'expiry:' || (:now - ((id % 8) * 1728000) + 43200),
    :now - ((id % 8) * 1728000) + 43200,
    :now - ((id % 8) * 1728000)
FROM client
WHERE mac IS NOT NULL AND id % 4 = 0
UNION ALL
SELECT
    (SELECT id FROM provider WHERE kind = 'dhcp_lease' AND provider_key = 'dnsmasq'),
    id,
    'dnsmasq',
    last_address,
    mac,
    hostname,
    NULL,
    NULL,
    NULL,
    vendor_hint,
    'reserved',
    interface_id,
    NULL,
    'observed_day:' || ((:now - ((id % 8) * 1728000)) / 86400 * 86400),
    NULL,
    :now - ((id % 8) * 1728000)
FROM client
WHERE mac IS NOT NULL AND id % 7 = 0;

-- ---------------------------------------------------------------------------
-- ONE MACHINE, TWO SERVERS, TWO VLANs. This is the deployment the dhcp_lease
-- kind was made concurrent for, and it is seeded explicitly rather than left to
-- fall out of the blocks above, because it is the claim the decision rests on.
--
-- The client below already holds a lease from the first server, on the interface
-- it was discovered behind. This adds a lease from the SECOND server, at a
-- different address, on a DIFFERENT interface. It is ONE client row with TWO
-- leases, and that is the truth rather than a collapse: the identity cascade keys
-- on the DHCP client identifier and then on the MAC, neither of them scoped to an
-- interface, so the same machine reported by two servers is the same machine.
--
-- The second interface is derived arithmetically from the first, so nothing here
-- assumes how many interfaces exist or which one anything sits behind; the
-- expression cannot yield the interface the client is already on.
-- ---------------------------------------------------------------------------
INSERT INTO dhcp_lease (provider_id, client_id, backend, address, mac, hostname,
                        dhcp_client_id, duid, iaid,
                        vendor_hint, lease_state, interface_id, starts_at, generation_key,
                        expires_at, observed_at)
SELECT
    (SELECT id FROM provider WHERE kind = 'dhcp_lease' AND provider_key = 'dnsmasq'),
    c.id,
    'dnsmasq',
    a.address_v4,
    c.mac,
    c.hostname,
    NULL,
    NULL,
    NULL,
    c.vendor_hint,
    'active',
    1 + (c.interface_id % :interfaces),
    NULL,
    'expiry:' || (:now + 43200),
    :now + 43200,
    :now
FROM client AS c
JOIN synth_address AS a ON a.slot = :clients + 3
WHERE c.mac IS NOT NULL
  AND c.interface_id IS NOT NULL
  AND c.id = (SELECT min(id) FROM client
              WHERE mac IS NOT NULL AND interface_id IS NOT NULL);

-- ---------------------------------------------------------------------------
-- Flows — the largest growing table, one row per filter-log record.
--
-- Timestamps walk backwards from :now in 97-second steps, so the seeded
-- history is deterministic, dense near the present and long enough for a
-- 90-day retention horizon to bite.
--
-- Shape of the generated population, in the three traffic directions
-- classified_flow derives:
--   i % 3 = 0                inter_interface: both ends sit behind an interface
--   i % 3 = 1 and i % 5 = 0  inbound: an outside source reaching a client,
--                            logged on the upstream interface with pf `dir` in
--   i % 3 = 1 and i % 23 = 0 (and not the above) an outside source reaching the
--                            upstream interface's own address: THIS FIREWALL is its
--                            destination, which the recognition below records
--   every other flow         outbound: the destination is outside every interface
--   i % 3 = 2                the flow will also carry a site-name attribution
--   i % 7 = 0                blocked; 'reject' rather than 'block' when i % 29 = 0
--   i % 37 = 0 (not blocked) an action the collector could not name: 'unknown'
--   i % 11 = 0               the rid matches no known rule -> rule_lookup_state
--                            not_found, and the record names the non-match reason
--   i % 13 = 0               the raw device name is absent from the interface map
-- The moduli are coprime with :clients in the default run, so every client
-- sees flows of every kind rather than one kind only.
--
-- The counter is generate_series rather than a recursive expression: this is the
-- one generator that runs to a million rows (the scale seed of sql/schema-checks.sh),
-- and P9 of specs/SPEC-backend-completion-plugins.md asks for it set-based. It counts
-- in BIGINT because the products of the counter below pass the INTEGER range there.
-- ---------------------------------------------------------------------------
WITH counter (i) AS (
    SELECT generate_series(CAST(1 AS BIGINT), :flow_rows)
),
kinded AS (
    SELECT
        i,
        CASE
            WHEN i % 3 = 0 THEN 'inter_interface'
            WHEN i % 3 = 1 AND i % 5 = 0 THEN 'inbound'
            WHEN i % 3 = 1 AND i % 23 = 0 THEN 'outside'
            ELSE 'outbound'
        END AS kind
    FROM counter
),
chosen AS (
    SELECT
        i,
        kind,
        :now - (i * 97)                                      AS observed_at,
        CASE WHEN kind IN ('inter_interface', 'outbound')
             THEN ((i - 1) % :clients) + 1 END               AS src_client_id,
        CASE kind
            WHEN 'inter_interface' THEN (i % :clients) + 1
            WHEN 'inbound' THEN ((i - 1) % :clients) + 1
        END                                                  AS dst_client_id,
        i % 7 = 0                                            AS is_blocked,
        i % 11 = 0                                           AS rule_missing,
        i % 13 = 0                                           AS interface_missing,
        -- The record's address family. A filter-log record reports ONE
        -- ipversion, so both endpoints below are taken from the same family.
        i % :ipv6_every = 0                                  AS is_ipv6,
        CASE WHEN kind IN ('inter_interface', 'outbound') THEN ((i - 1) % :clients) + 1
             ELSE 1000000 + (i % 4000) END                   AS src_slot,
        CASE kind
            WHEN 'inter_interface' THEN (i % :clients) + 1
            WHEN 'inbound' THEN ((i - 1) % :clients) + 1
            WHEN 'outside' THEN 900000 + :interfaces + 1
            ELSE 1000000 + (i % 4000)
        END                                                  AS dst_slot
    FROM kinded
),
placed AS (
    SELECT
        i, kind, observed_at, src_client_id, dst_client_id,
        is_blocked, rule_missing, interface_missing, is_ipv6,
        CASE WHEN src_client_id IS NOT NULL
             THEN ((src_client_id - 1) % :interfaces) + 1 END AS src_interface_id,
        CASE WHEN dst_client_id IS NOT NULL
             THEN ((dst_client_id - 1) % :interfaces) + 1 END AS dst_interface_id,
        -- The interface the record was logged on: the source's for a flow leaving
        -- a client, the upstream interface's for one arriving from outside.
        CASE WHEN kind IN ('inter_interface', 'outbound')
             THEN ((src_client_id - 1) % :interfaces) + 1
             ELSE :interfaces + 1 END                         AS logged_interface_id,
        CASE WHEN is_ipv6 THEN src.address_v6 ELSE src.address_v4 END AS src_address,
        CASE WHEN is_ipv6 THEN dst.address_v6 ELSE dst.address_v4 END AS dst_address
    FROM chosen
    JOIN synth_address AS src ON src.slot = src_slot
    JOIN synth_address AS dst ON dst.slot = dst_slot
)
INSERT INTO flow (id, log_digest, observed_at, ingested_at, interface_device,
                  interface_lookup_state, src_interface_id, dst_interface_id,
                  src_client_id, dst_client_id, src_address, dst_address,
                  src_port, dst_port, protocol, ip_version, action, direction,
                  log_reason, packet_bytes, rid, rule_id, rule_lookup_state,
                  ip_id, tcp_seq, traffic_scope)
SELECT
    i,
    format('log-digest-%s', i),
    observed_at,
    observed_at + 5,
    CASE WHEN interface_missing
         THEN format('unmapped-device-%s', i)
         ELSE format('device-%s', logged_interface_id) END,
    CASE WHEN interface_missing THEN 'not_found' ELSE 'resolved' END,
    src_interface_id,
    dst_interface_id,
    src_client_id,
    dst_client_id,
    src_address,
    dst_address,
    1024 + ((i * 17) % 64000),
    1 + ((i * 13) % 65000),
    CASE WHEN i % 2 = 0 THEN 'tcp' ELSE 'udp' END,
    -- The family the filter log reported. It is the only column from which a
    -- v4-against-v6 split is answerable: an address column alone cannot be
    -- classified, and the project forbids inferring an addressing plan.
    CASE WHEN is_ipv6 THEN 6 ELSE 4 END,
    -- A refusal is 'block', or 'reject' when pf answered it; a record whose action
    -- the collector could not name is 'unknown', and is neither allowed nor blocked.
    CASE WHEN is_blocked AND i % 29 = 0 THEN 'reject'
         WHEN is_blocked THEN 'block'
         WHEN i % 37 = 0 THEN 'unknown'
         ELSE 'pass' END,
    -- pf's `dir` on the interface the record was logged on. A packet arriving
    -- from outside is `in` on the upstream interface.
    CASE WHEN kind IN ('inbound', 'outside') THEN 'in'
         WHEN i % 2 = 0 THEN 'in' ELSE 'out' END,
    -- The reason the record was logged, from the established set
    -- (internal/store/vocab/rows.go, LogReasons; survey, "The `reason` field's
    -- values, read for step 5"): `match` when a rule decided, and one of the
    -- drops no rule expresses on the records whose rid matches no rule.
    -- One record in nineteen carries no reason at all, which blocked_decision
    -- places as a refusal whose reason was not recorded.
    CASE WHEN i % 11 = 0 THEN 'state-mismatch' WHEN i % 19 = 0 THEN NULL ELSE 'match' END,
    40 + ((i * 37) % 1460),
    CASE WHEN rule_missing
         THEN format('orphan-rule-label-%s', i)
         ELSE format('rule-label-%s', ((i - 1) % :rules) + 1) END,
    CASE WHEN rule_missing THEN NULL ELSE ((i - 1) % :rules) + 1 END,
    CASE WHEN rule_missing THEN 'not_found' ELSE 'resolved' END,
    -- The IPv4 identification and the TCP sequence number, the two fields that pair
    -- the two records of one connection: none on IPv6, no sequence off TCP.
    CASE WHEN is_ipv6 THEN NULL ELSE (i * 31) % 65536 END,
    CASE WHEN i % 2 = 0 THEN (i * 7919) % 4294967296 END,
    -- Interface membership and nothing else. The CHECK on the column rejects any
    -- other value, so this expression cannot drift from the schema's. The ends that
    -- are this firewall are recognised further down, as classification does it.
    CASE WHEN src_interface_id IS NOT NULL AND dst_interface_id IS NOT NULL
         THEN 'east_west' ELSE 'north_south' END
FROM placed;

-- ---------------------------------------------------------------------------
-- Resolver lookups, and the site names inferred from them.
--
-- Only the north-south flows with i % 3 = 2 get an attribution, so every
-- client also has unattributed flows: the Client screen must return those with
-- their address, country and operator and a null site name rather than
-- dropping them, and the attribution rate must be below 100 per cent.
-- ---------------------------------------------------------------------------
INSERT INTO dns_resolution (id, lookup_key, client_address, client_id, domain,
                            resolver, action, answer_source, rcode,
                            dnssec_status, looked_up_at, ingested_at,
                            interface_id, interface_lookup_state)
SELECT
    id,
    format('lookup-uuid-%s', id),
    src_address,
    src_client_id,
    format('name-%s.example-zone-%s.invalid', id % 997, id % 13),
    'unbound',
    'pass',
    -- Unbound's own `source` values, verbatim (survey, data source 5): every one
    -- the attribution rule admits appears.
    CASE WHEN id % 5 = 0 THEN 'Cache' WHEN id % 17 = 0 THEN 'Local-data' ELSE 'Recursion' END,
    'NOERROR',
    -- The validation verdict. Synthesised, for the reason the flow reasons
    -- above are: the survey establishes the field and not its value set. One
    -- lookup in nine carries no verdict at all, which is "not reported" and
    -- not "unvalidated" -- the distinction the nullable column exists for.
    CASE WHEN id % 7 = 3 THEN NULL
         ELSE format('dnssec-status-%s', id % 3) END,
    -- Within the default attribution_max_delay_seconds, as the rule requires.
    observed_at - (1 + (id % 5)),
    observed_at,
    -- The interface behind the lookup's client address, as classification places it.
    src_interface_id,
    CASE WHEN src_interface_id IS NULL THEN 'not_found' ELSE 'resolved' END
FROM flow
WHERE id % 3 = 2;

-- Every one by timing, the 5A method; the resolver's cache names some of them exactly,
-- further down, once the flows' final classification is written.
INSERT INTO domain_attribution (flow_id, dns_resolution_id, site_name,
                                correlation_delay_seconds, attributed_at, method)
SELECT id, id, format('name-%s.example-zone-%s.invalid', id % 997, id % 13),
       1 + (id % 5), observed_at, 'lookup_timing'
FROM flow
WHERE id % 3 = 2;

-- A flow observed two seconds after the retention horizon, named by a lookup made two
-- seconds before it: the purge keeps that lookup, because the attribution of a flow it
-- keeps still names it. The horizon is read from the setting, as the purge reads it, and
-- the flow takes the shape of the first flow.
-- Like flow 2000000002 below, it lies outside the live-validation window, and
-- sql/schema-checks.sh (RC-FOLLOW-AC4) fails if it ever moves inside it.
INSERT INTO flow (id, log_digest, observed_at, ingested_at, interface_device,
                  interface_lookup_state, src_interface_id, dst_interface_id,
                  src_client_id, dst_client_id, src_address, dst_address,
                  src_port, dst_port, protocol, ip_version, action, direction,
                  log_reason, packet_bytes, rid, rule_id, rule_lookup_state, traffic_scope)
SELECT 2000000001, 'log-digest-at-the-horizon', h.horizon + 2, h.horizon + 7, interface_device,
       interface_lookup_state, src_interface_id, dst_interface_id, src_client_id, dst_client_id,
       src_address, dst_address, src_port, dst_port, protocol, ip_version, action, direction,
       log_reason, packet_bytes, rid, rule_id, rule_lookup_state, traffic_scope
FROM flow
CROSS JOIN (SELECT :now - CAST(value AS BIGINT) AS horizon FROM setting
      WHERE key = 'retention_seconds') AS h
WHERE flow.id = 1;

INSERT INTO dns_resolution (id, lookup_key, client_address, client_id, domain,
                            resolver, action, answer_source, rcode, dnssec_status,
                            looked_up_at, ingested_at, interface_id, interface_lookup_state)
SELECT 2000000001, 'lookup-uuid-at-the-horizon', src_address, src_client_id,
       'name-at-the-horizon.example-zone.invalid', 'unbound', 'pass', 'Recursion', 'NOERROR',
       NULL, observed_at - 4, observed_at, src_interface_id,
       CASE WHEN src_interface_id IS NULL THEN 'not_found' ELSE 'resolved' END
FROM flow WHERE id = 2000000001;

INSERT INTO domain_attribution (flow_id, dns_resolution_id, site_name,
                                correlation_delay_seconds, attributed_at, method)
SELECT 2000000001, 2000000001, 'name-at-the-horizon.example-zone.invalid', 4, observed_at,
       'lookup_timing'
FROM flow WHERE id = 2000000001;

-- Lookups from an address no interface holds -- a client the classification could
-- not place -- in both families. They name no client and their interface is
-- 'not_found', so no flow is ever attributed from them.
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 40
)
INSERT INTO dns_resolution (id, lookup_key, client_address, client_id, domain,
                            resolver, action, answer_source, rcode, dnssec_status,
                            looked_up_at, ingested_at, interface_id, interface_lookup_state)
SELECT
    1100000000 + n,
    format('unplaced-lookup-uuid-%s', n),
    CASE WHEN n % 2 = 0 THEN a.address_v6 ELSE a.address_v4 END,
    NULL,
    format('unplaced-name-%s.example-zone-%s.invalid', n % 23, n % 5),
    'unbound',
    'pass',
    CASE WHEN n % 3 = 0 THEN 'Local' ELSE 'Recursion' END,
    'NOERROR',
    NULL,
    :now - (n * 613),
    :now - (n * 613) + 2,
    NULL,
    'not_found'
FROM counter
JOIN synth_address AS a ON a.slot = 1000000 + 3000 + n;

-- Lookups whose `client` was a host name rather than an address, the resolver's
-- report having replaced the address by its reverse lookup. One in three resolved
-- through the leases to one address; the others named a host no lease or several
-- leases held, and keep the logged name in client_address, place nowhere and
-- attribute nothing. The names are synthesised and match no lease below.
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 12
)
INSERT INTO dns_resolution (id, lookup_key, client_address, client_hostname, client_resolution,
                            client_id, domain, resolver, action, answer_source, rcode,
                            dnssec_status, looked_up_at, ingested_at, interface_id,
                            interface_lookup_state)
SELECT
    1200000000 + n,
    format('hostname-lookup-uuid-%s', n),
    CASE WHEN n % 3 = 0 THEN c.last_address
         ELSE format('host-name-%s.example-zone.invalid', n) END,
    format('host-name-%s.example-zone.invalid', n),
    CASE n % 3 WHEN 0 THEN 'lease_hostname' WHEN 1 THEN 'ambiguous_hostname'
               ELSE 'unknown_hostname' END,
    CASE WHEN n % 3 = 0 THEN c.id END,
    format('hostname-name-%s.example-zone-%s.invalid', n, n % 3),
    'unbound',
    'pass',
    'Recursion',
    'NOERROR',
    NULL,
    :now - (n * 457),
    :now - (n * 457) + 2,
    CASE WHEN n % 3 = 0 THEN c.interface_id END,
    CASE WHEN n % 3 = 0 THEN 'resolved' ELSE 'not_found' END
FROM counter
JOIN client AS c ON c.id = ((n - 1) % :clients) + 1;

-- ---------------------------------------------------------------------------
-- The blocklists the resolver refused lookups against.
--
-- The NAME is observed: the endpoint returns it verbatim on every row. The
-- PURPOSE is user input, so three of the four are classified and the fourth is
-- left alone -- the normal state, and the one the "purpose not assigned"
-- rendering exists for. Nothing derives a purpose from a name here or
-- anywhere else; the names below are synthesised from a counter and carry no
-- meaning a machine could read.
-- ---------------------------------------------------------------------------
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 4
)
INSERT INTO blocklist (id, name, purpose, purpose_assigned_at, first_seen_at, last_seen_at)
SELECT
    n,
    format('example-blocklist-%s', n),
    CASE n WHEN 1 THEN 'advertising' WHEN 2 THEN 'threat' WHEN 3 THEN 'tracking' END,
    CASE WHEN n <= 3 THEN :now - 86400 END,
    :now - 2592000,
    :now
FROM counter;

-- Blocked lookups, which the pass-only rows above do not exercise.
--
-- Four fifths name the list that refused them and one fifth does not: the
-- endpoint does not attribute every block, and "blocked, list not recorded" is
-- a modelled state rather than a silent merge into a bucket. Every one of the
-- four lists is used, the unclassified one included, so a query grouping by
-- purpose has an unassigned group to return.
--
-- These rows carry no attribution, deliberately: a blocked lookup produces no
-- flow, so there is nothing to attribute and nothing to correlate.
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 400
)
INSERT INTO dns_resolution (id, lookup_key, client_address, client_id, domain,
                            resolver, action, answer_source, rcode, dnssec_status,
                            blocklist_id, looked_up_at, ingested_at,
                            interface_id, interface_lookup_state)
SELECT
    1000000000 + n,
    format('blocked-lookup-uuid-%s', n),
    c.last_address,
    c.id,
    format('blocked-name-%s.example-zone-%s.invalid', n % 211, n % 7),
    'unbound',
    CASE WHEN n % 8 = 0 THEN 'drop' ELSE 'block' END,
    'Local',
    'NXDOMAIN',
    CASE WHEN n % 6 = 0 THEN NULL ELSE format('dnssec-status-%s', n % 3) END,
    CASE WHEN n % 5 = 0 THEN NULL ELSE ((n - 1) % 4) + 1 END,
    :now - ((n * 97) % 86400),
    :now,
    c.interface_id,
    'resolved'
FROM counter
JOIN client AS c ON c.id = ((n - 1) % :clients) + 1;

-- ---------------------------------------------------------------------------
-- Geo / ASN cache, one row per synthesised external address. Roughly one in
-- thirty-seven is a modelled cache miss rather than an absent row, so the Map
-- and Client screens can show that the enrichment did not answer instead of
-- silently dropping the volume.
-- ---------------------------------------------------------------------------
-- Every external slot is enriched in BOTH families, because a flow of either
-- family can name it and the Map and Client screens join geo_asn on the address
-- the flow actually carried. Enriching one family only would make every IPv6
-- destination a cache miss, which would look like a dataset problem rather than
-- a seed that had not been extended.
WITH RECURSIVE counter (j) AS (
    SELECT 0
    UNION ALL
    SELECT j + 1 FROM counter WHERE j < greatest(3999, :pair_rows)
),
generated AS (
    SELECT
        j,
        family,
        CASE WHEN family = 6 THEN a.address_v6 ELSE a.address_v4 END AS address,
        chr(65 + (j % 26)) || chr(65 + ((j / 26) % 26)) AS country_code,
        j % 37 = 0 AS is_miss
    FROM counter
    JOIN synth_address AS a ON a.slot = 1000000 + j
    CROSS JOIN (SELECT 4 AS family UNION ALL SELECT 6) AS families
)
INSERT INTO geo_asn (address, provider_id, lookup_state, country_code, country_name,
                     latitude, longitude, asn, operator, dataset_build_at, looked_up_at)
SELECT
    address,
    (SELECT id FROM provider WHERE kind = 'ip_geolocation' AND is_active),
    CASE WHEN is_miss THEN 'miss' ELSE 'resolved' END,
    CASE WHEN is_miss THEN NULL ELSE country_code END,
    CASE WHEN is_miss THEN NULL ELSE format('country-name-%s', country_code) END,
    CASE WHEN is_miss THEN NULL ELSE ((j % 180) - 90) * 1.0 END,
    CASE WHEN is_miss THEN NULL ELSE ((j % 360) - 180) * 1.0 END,
    CASE WHEN is_miss THEN NULL ELSE 1000 + j END,
    CASE WHEN is_miss THEN NULL ELSE format('operator-%s', j % 97) END,
    CASE WHEN is_miss THEN NULL ELSE :now - 604800 END,
    :now - ((j % 100) * 86400)
FROM generated;

-- ---------------------------------------------------------------------------
-- Security events, and the per-provider rule-info cache that gives them a
-- severity.
--
-- Every event is attributed to the active provider of the security_event kind
-- and carries the key that provider guarantees stable -- for this one, the eve
-- file id and the byte offset inside it, composed into a single text key by
-- the collector. The ingestion coordinate is not stored as columns here; that
-- is eve_ingest_cursor's concern.
--
-- Rule identities are text. Forty-nine of the fifty are numeric strings and
-- one is deliberately NON-NUMERIC, so a provider whose rules are named rather
-- than numbered is exercised. Ten of the numeric ones are absent from the
-- cache, so the Alerts screen has to render an explicit unknown severity.
--
-- normalised_severity is NULL on every row: Suricata ships no severity inside
-- the event (survey, gap 3), and this restructuring changes nothing about it.
-- ---------------------------------------------------------------------------
WITH RECURSIVE counter (m) AS (
    SELECT 1
    UNION ALL
    SELECT m + 1 FROM counter WHERE m < :alerts
),
generated AS (
    SELECT
        m,
        -- Dense over the last few days, then stretched back over four months,
        -- so the recent window is busy enough to exercise the Alerts screen
        -- and a finite retention horizon still has something to purge.
        :now - (m * 601) - (greatest(m - 250, 0) * 40000) AS occurred_at,
        ((m - 1) % :clients) + 1                     AS src_client_id,
        -- Three rotated files whatever :alerts is, so the ingestion cursor
        -- always has a watermark per file to record.
        1 + (((m - 1) * 3) / :alerts)                AS file_number,
        m * 4096                                     AS byte_position,
        m % :ipv6_every = 0                          AS is_ipv6
    FROM counter
)
INSERT INTO security_event (id, provider_id, provider_event_key, occurred_at, ingested_at,
                            rule_identity, signature, event_action, normalised_severity,
                            src_address, src_port, dst_address, dst_port, protocol,
                            in_interface_device, src_client_id, src_interface_id, flow_ref)
SELECT
    m,
    (SELECT id FROM provider WHERE kind = 'security_event' AND is_active),
    format('eve-file-%s:%s', file_number, byte_position),
    occurred_at,
    occurred_at + 30,
    CASE WHEN m % 50 = 3
         THEN 'named-rule-identity-alpha'
         ELSE format('%s', 1000000 + (m % 50)) END,
    format('signature-text-%s', m % 50),
    CASE WHEN m % 4 = 0 THEN 'blocked' ELSE 'allowed' END,
    NULL,
    (SELECT CASE WHEN g.is_ipv6 THEN a.address_v6 ELSE a.address_v4 END
     FROM synth_address AS a WHERE a.slot = g.src_client_id),
    1024 + ((m * 19) % 64000),
    (SELECT CASE WHEN g.is_ipv6 THEN a.address_v6 ELSE a.address_v4 END
     FROM synth_address AS a WHERE a.slot = 1000000 + (m % 4000)),
    1 + ((m * 7) % 65000),
    CASE WHEN m % 2 = 0 THEN 'tcp' ELSE 'udp' END,
    format('device-%s', ((src_client_id - 1) % :interfaces) + 1),
    src_client_id,
    ((src_client_id - 1) % :interfaces) + 1,
    NULL
FROM generated AS g;

-- The cache. normalised_severity is opnview's ordered vocabulary;
-- provider_severity keeps the raw numeric string the provider reported, so the
-- normalisation stays auditable. The mapping 1..4 -> critical, high, medium,
-- low is documented in docs/data-model.md.
WITH RECURSIVE counter (x) AS (
    SELECT 0
    UNION ALL
    SELECT x + 1 FROM counter WHERE x < 39
),
raw AS (
    SELECT x, 1 + (x % 4) AS provider_severity FROM counter
)
INSERT INTO provider_rule_info (provider_id, rule_identity, normalised_severity,
                                provider_severity, category, rule_source, fetched_at)
SELECT
    (SELECT id FROM provider WHERE kind = 'security_event' AND is_active),
    CASE WHEN x = 3 THEN 'named-rule-identity-alpha' ELSE format('%s', 1000000 + x) END,
    CASE provider_severity
        WHEN 1 THEN 'critical'
        WHEN 2 THEN 'high'
        WHEN 3 THEN 'medium'
        ELSE 'low'
    END,
    format('%s', provider_severity),
    format('category-%s', x % 7),
    format('rule-source-%s', x % 3),
    :now - 3600
FROM raw;

-- ---------------------------------------------------------------------------
-- eve.json ingestion cursor: one watermark per rotated file, with the rotation
-- state. 'lost' is the case where rotation discarded the file the watermark
-- referred to, so the gap is permanent and recorded as such.
--
-- This is a DIFFERENT guarantee from the one on security_event. The unique key
-- here answers "where did the reader stop in this file"; the unique key there
-- answers "have I already stored this event". Merging them would lose one of
-- the two.
-- ---------------------------------------------------------------------------
WITH RECURSIVE counter (m) AS (
    SELECT 1
    UNION ALL
    SELECT m + 1 FROM counter WHERE m < :alerts
),
watermarks AS (
    SELECT 1 + (((m - 1) * 3) / :alerts) AS file_number, m * 4096 AS byte_position
    FROM counter
)
INSERT INTO eve_ingest_cursor (file_id, byte_offset, file_sequence, rotation_state, observed_at)
SELECT 'eve-file-0', 0, 0, 'lost', :now - 604800
UNION ALL
SELECT format('eve-file-%s', file_number), max(byte_position), file_number,
       CASE WHEN file_number = 3 THEN 'current' ELSE 'rotated' END, :now
FROM watermarks
GROUP BY file_number;

-- ---------------------------------------------------------------------------
-- Daily per-pair volume, DERIVED rather than collected.
--
-- No collector writes this table and none will: the only per-pair endpoint
-- carries neither a port nor a protocol, and `flow` carries both, so these rows
-- are step 5's to compute from `flow` (internal/store/derive.sql,
-- insert_pair_volume). The seed writes them as that derivation does, which is why
-- this block names no provider; service_port is the flow's destination port.
--
-- The de-duplication it has to respect is unchanged, and the seed still exercises
-- it: a per-pair figure is direction-free, so the seed offers every pair twice
-- with the endpoints swapped and the key collapses them to one logical volume.
-- After this statement the table holds :pair_rows rows, not twice that.
-- ---------------------------------------------------------------------------
WITH RECURSIVE counter (p) AS (
    SELECT 1
    UNION ALL
    SELECT p + 1 FROM counter WHERE p < :pair_rows
),
pairs AS (
    SELECT
        p,
        (((:now / 86400) - (p % 120)) * 86400) AS day_start_at,
        -- The pair's family. Both ends are of one family, as a real conversation
        -- is, and the canonical ordering below is lexicographic over whichever
        -- form that produced.
        CASE WHEN p % :ipv6_every = 0 THEN local.address_v6 ELSE local.address_v4 END
            AS local_address,
        CASE WHEN p % :ipv6_every = 0 THEN peer.address_v6 ELSE peer.address_v4 END
            AS peer_address
    FROM counter
    JOIN synth_address AS local ON local.slot = ((p - 1) % :clients) + 1
    JOIN synth_address AS peer ON peer.slot = 1000000 + p
),
doubled AS (
    SELECT p, day_start_at, local_address AS a, peer_address AS b, 'out' AS observed_direction
    FROM pairs
    UNION ALL
    SELECT p, day_start_at, peer_address AS a, local_address AS b, 'in' AS observed_direction
    FROM pairs
)
INSERT INTO pair_volume_observation
    (day_start_at, endpoint_low, endpoint_high, service_port, protocol,
     octets, packets, observed_direction, observed_interface_device,
     last_seen_at, ingested_at)
SELECT
    day_start_at,
    least(a, b),
    greatest(a, b),
    1 + (p % 1000),
    CASE WHEN p % 2 = 0 THEN 'tcp' ELSE 'udp' END,
    1000.0 + p,
    10.0 + (p % 50),
    observed_direction,
    format('device-%s', ((p - 1) % :interfaces) + 1),
    day_start_at + 86399,
    :now
FROM doubled
ORDER BY p, observed_direction
ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------------
-- THIS FIREWALL AS AN END, AND THE TWO LEGS OF ONE CONNECTION.
--
-- Records the step-5A live corrections are about, generated from counters like
-- every other row and named by nothing real:
--   * a client reaching the firewall's own address on its own interface;
--   * a client's connection to an outside address logged twice: `in` on the
--     client's interface and `out` on the upstream one. Over IPv4 the second leg's
--     source is the firewall's upstream address and its port another, as outbound
--     NAT writes it; over IPv6 it is the client's, unchanged. Both legs carry the
--     same identification and sequence number, and each names the other;
--   * `out` records on the upstream interface sourced by this firewall with no first
--     leg: not paired, which is all opnview ever says of them (decision 3 as
--     amended);
--   * a record with both ends outside, logged on the upstream interface, which
--     pf's `dir` places.
-- They are written with neither firewall end recognised, exactly as the
-- collector stores a record, and the recognition below records every end that is
-- this firewall, as classification does.
-- ---------------------------------------------------------------------------
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 60
),
legs AS (
    SELECT n,
           ((n - 1) % :clients) + 1                         AS client_id,
           ((((n - 1) % :clients) + 1 - 1) % :interfaces) + 1 AS interface_id,
           :now - 3600 - n * 613                            AS observed_at,
           n % 3 = 0                                        AS is_ipv6
    FROM counter
)
INSERT INTO flow (id, log_digest, observed_at, ingested_at, interface_device,
                  interface_lookup_state, src_interface_id, dst_interface_id,
                  src_client_id, dst_client_id, src_address, dst_address,
                  src_port, dst_port, protocol, ip_version, action, direction,
                  log_reason, packet_bytes, rid, rule_id, rule_lookup_state,
                  ip_id, tcp_seq, pair_outcome, paired_flow_id, traffic_scope)
SELECT 2100000000 + 2 * l.n - 1, format('log-digest-first-leg-%s', l.n), l.observed_at,
       l.observed_at + 5, format('device-%s', l.interface_id), 'resolved', l.interface_id, CAST(NULL AS BIGINT),
       l.client_id, CAST(NULL AS BIGINT),
       CASE WHEN l.is_ipv6 THEN c.address_v6 ELSE c.address_v4 END,
       CASE WHEN l.is_ipv6 THEN x.address_v6 ELSE x.address_v4 END,
       40000 + l.n, 443, 'tcp', CASE WHEN l.is_ipv6 THEN 6 ELSE 4 END, 'pass', 'in', 'match',
       60 + l.n, 'rule-label-1', 1, 'resolved',
       CASE WHEN l.is_ipv6 THEN NULL ELSE (l.n * 97) % 65536 END, 1000000 + l.n * 7919,
       'first_leg', 2100000000 + 2 * l.n, 'north_south'
FROM legs AS l
JOIN synth_address AS c ON c.slot = l.client_id
JOIN synth_address AS x ON x.slot = 1000000 + 500 + l.n
UNION ALL
SELECT 2100000000 + 2 * l.n, format('log-digest-second-leg-%s', l.n), l.observed_at + (l.n % 2),
       l.observed_at + 6, format('device-%s', :interfaces + 1), 'resolved',
       CASE WHEN l.is_ipv6 THEN l.interface_id END, NULL,
       CASE WHEN l.is_ipv6 THEN l.client_id END, NULL,
       CASE WHEN l.is_ipv6 THEN c.address_v6 ELSE u.address_v4 END,
       CASE WHEN l.is_ipv6 THEN x.address_v6 ELSE x.address_v4 END,
       CASE WHEN l.is_ipv6 THEN 40000 + l.n ELSE 50000 + l.n END, 443, 'tcp',
       CASE WHEN l.is_ipv6 THEN 6 ELSE 4 END, 'pass', 'out', 'match',
       60 + l.n, 'rule-label-1', 1, 'resolved',
       CASE WHEN l.is_ipv6 THEN NULL ELSE (l.n * 97) % 65536 END, 1000000 + l.n * 7919,
       'second_leg', 2100000000 + 2 * l.n - 1, 'north_south'
FROM legs AS l
JOIN synth_address AS c ON c.slot = l.client_id
JOIN synth_address AS x ON x.slot = 1000000 + 500 + l.n
JOIN synth_address AS u ON u.slot = 900000 + :interfaces + 1;

WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 40
)
INSERT INTO flow (id, log_digest, observed_at, ingested_at, interface_device,
                  interface_lookup_state, src_interface_id, dst_interface_id,
                  src_client_id, dst_client_id, src_address, dst_address,
                  src_port, dst_port, protocol, ip_version, action, direction,
                  log_reason, packet_bytes, rid, rule_id, rule_lookup_state,
                  ip_id, tcp_seq, pair_outcome, paired_flow_id, traffic_scope)
SELECT 2100001000 + n, format('log-digest-firewall-own-%s', n), :now - n * 90000,
       :now - n * 90000 + 5, format('device-%s', :interfaces + 1), 'resolved', NULL, NULL,
       NULL, NULL, u.address_v4, x.address_v4, 30000 + n, 53, 'udp', 4, 'pass', 'out', 'match',
       70 + n, 'rule-label-1', 1, 'resolved', (n * 211) % 65536, NULL,
       'not_paired',
       NULL, 'north_south'
FROM counter
JOIN synth_address AS x ON x.slot = 1000000 + 700 + n
JOIN synth_address AS u ON u.slot = 900000 + :interfaces + 1;

WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 30
)
INSERT INTO flow (id, log_digest, observed_at, ingested_at, interface_device,
                  interface_lookup_state, src_interface_id, dst_interface_id,
                  src_client_id, dst_client_id, src_address, dst_address,
                  src_port, dst_port, protocol, ip_version, action, direction,
                  log_reason, packet_bytes, rid, rule_id, rule_lookup_state,
                  ip_id, tcp_seq, traffic_scope)
SELECT 2100002000 + n, format('log-digest-to-this-firewall-%s', n), :now - n * 1000,
       :now - n * 1000 + 5, format('device-%s', ((((n - 1) % :clients) + 1 - 1) % :interfaces) + 1),
       'resolved', ((((n - 1) % :clients) + 1 - 1) % :interfaces) + 1, NULL,
       ((n - 1) % :clients) + 1, NULL, c.address_v4, f.address_v4, 20000 + n, 53, 'udp', 4,
       CASE WHEN n % 5 = 0 THEN 'block' ELSE 'pass' END, 'in', 'match', 64, 'rule-label-1', 1,
       'resolved', (n * 13) % 65536, NULL, 'north_south'
FROM counter
JOIN synth_address AS c ON c.slot = ((n - 1) % :clients) + 1
JOIN synth_address AS f ON f.slot = 900000 + ((((n - 1) % :clients) + 1 - 1) % :interfaces) + 1;

WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 10
)
INSERT INTO flow (id, log_digest, observed_at, ingested_at, interface_device,
                  interface_lookup_state, src_interface_id, dst_interface_id,
                  src_client_id, dst_client_id, src_address, dst_address,
                  src_port, dst_port, protocol, ip_version, action, direction,
                  log_reason, packet_bytes, rid, rule_id, rule_lookup_state, traffic_scope)
SELECT 2100003000 + n, format('log-digest-outside-to-outside-%s', n), :now - n * 1300,
       :now - n * 1300 + 5, format('device-%s', :interfaces + 1), 'resolved', NULL, NULL, NULL, NULL,
       s.address_v4, d.address_v4, 10000 + n, 22, 'tcp', 4, 'block', 'in', 'match', 52,
       'rule-label-1', 1, 'resolved', 'north_south'
FROM counter
JOIN synth_address AS s ON s.slot = 1000000 + 800 + n
JOIN synth_address AS d ON d.slot = 1000000 + 900 + n;

-- The recognition, as classification makes it (internal/store/derive.sql,
-- classify_flow_*): an end whose address this firewall held at the record's
-- instant -- this_firewall_address, with the margin of the default discovery
-- interval, 300 s -- is this firewall, records the interface the address belonged
-- to and no client.
UPDATE flow
SET dst_is_this_firewall = true,
    dst_client_id = NULL,
    dst_interface_id = (SELECT h.interface_id FROM this_firewall_address AS h
                        WHERE h.address = flow.dst_address
                          AND h.first_seen_at - 300 <= flow.observed_at
                          AND (h.is_current = 1 OR h.last_seen_at + 300 >= flow.observed_at)
                        ORDER BY h.last_seen_at DESC, h.interface_id
                        LIMIT 1),
    traffic_scope = 'this_firewall'
WHERE EXISTS (SELECT 1 FROM this_firewall_address AS h
              WHERE h.address = flow.dst_address
                AND h.first_seen_at - 300 <= flow.observed_at
                AND (h.is_current = 1 OR h.last_seen_at + 300 >= flow.observed_at));

UPDATE flow
SET src_is_this_firewall = true,
    src_client_id = NULL,
    src_interface_id = (SELECT h.interface_id FROM this_firewall_address AS h
                        WHERE h.address = flow.src_address
                          AND h.first_seen_at - 300 <= flow.observed_at
                          AND (h.is_current = 1 OR h.last_seen_at + 300 >= flow.observed_at)
                        ORDER BY h.last_seen_at DESC, h.interface_id
                        LIMIT 1),
    traffic_scope = 'this_firewall'
WHERE EXISTS (SELECT 1 FROM this_firewall_address AS h
              WHERE h.address = flow.src_address
                AND h.first_seen_at - 300 <= flow.observed_at
                AND (h.is_current = 1 OR h.last_seen_at + 300 >= flow.observed_at));

-- Security events whose source is this firewall, and lookups whose querier is: from
-- an interface's own address, and from `localhost`, the name a reverse lookup of the
-- loopback returns.
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 5
)
INSERT INTO security_event (id, provider_id, provider_event_key, occurred_at, ingested_at,
                            rule_identity, signature, event_action, normalised_severity,
                            src_address, src_port, dst_address, dst_port, protocol,
                            in_interface_device, src_client_id, src_interface_id,
                            src_is_this_firewall, flow_ref)
SELECT :alerts + n, (SELECT id FROM provider WHERE kind = 'security_event' AND is_active),
       format('eve-file-3:this-firewall-%s', n), :now - n * 700, :now - n * 700 + 30,
       format('%s', 1000000 + n), format('signature-text-%s', n), 'allowed', NULL,
       u.address_v4, 30000 + n, x.address_v4, 443, 'tcp', format('device-%s', :interfaces + 1),
       NULL, :interfaces + 1, 1, NULL
FROM counter
JOIN synth_address AS u ON u.slot = 900000 + :interfaces + 1
JOIN synth_address AS x ON x.slot = 1000000 + 600 + n;

WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 5
)
INSERT INTO dns_resolution (id, lookup_key, client_address, client_hostname, client_resolution,
                            client_id, client_is_this_firewall, domain, resolver, action,
                            answer_source, rcode, dnssec_status, looked_up_at, ingested_at,
                            interface_id, interface_lookup_state)
SELECT 1300000000 + n, format('this-firewall-lookup-uuid-%s', n), a.address_v4, NULL,
       'logged_address', CAST(NULL AS BIGINT), 1, format('firewall-name-%s.example-zone.invalid', n), 'unbound',
       'pass', 'Recursion', 'NOERROR', NULL, :now - n * 333, :now - n * 333 + 2,
       ((n - 1) % :interfaces) + 1, 'resolved'
FROM counter
JOIN synth_address AS a ON a.slot = 900000 + ((n - 1) % :interfaces) + 1
UNION ALL
SELECT 1300000100, 'this-firewall-localhost-lookup-uuid', 'localhost', 'localhost',
       'this_firewall_hostname', NULL, 1, 'firewall-name-localhost.example-zone.invalid',
       'unbound', 'pass', 'Recursion', 'NOERROR', NULL, :now - 222, :now - 220, NULL, 'not_found';

-- Half the unresolved host-name lookups have been examined by a lease pass since they
-- were ingested; the other half wait for the next one.
UPDATE dns_resolution
SET hostname_examined_at = ingested_at + 60
WHERE client_resolution IN ('ambiguous_hostname', 'unknown_hostname') AND id % 2 = 0;

-- Two lookups logged under a host name the local data held under one IPv4 and one IPv6
-- address (group C of specs/SPEC-step-5b-widget-api.md): one whose row reported no
-- querying family, which stays dual_stack_hostname and waits for a lease pass, and one
-- whose row reported the IPv6 family, resolved to the AAAA address. The names are
-- synthesised and match no lease.
INSERT INTO dns_resolution (id, lookup_key, client_address, client_hostname, client_resolution,
                            client_family, client_id, domain, resolver, action, answer_source,
                            rcode, dnssec_status, looked_up_at, ingested_at, interface_id,
                            interface_lookup_state)
SELECT 1300000200, 'dual-stack-lookup-uuid-1', 'dual-stack-host.example-zone.invalid',
       'dual-stack-host.example-zone.invalid', 'dual_stack_hostname', NULL, CAST(NULL AS BIGINT),
       'dual-stack-name-1.example-zone.invalid', 'unbound', 'pass', 'Recursion', 'NOERROR', NULL,
       :now - 444, :now - 442, CAST(NULL AS BIGINT), 'not_found'
UNION ALL
SELECT 1300000201, 'dual-stack-lookup-uuid-2', a.address_v6,
       'dual-stack-host.example-zone.invalid', 'local_data_hostname', 6, NULL,
       'dual-stack-name-2.example-zone.invalid', 'unbound', 'pass', 'Recursion', 'NOERROR', NULL,
       :now - 555, :now - 553, NULL, 'not_found'
FROM synth_address AS a WHERE a.slot = :clients + 2;

-- ---------------------------------------------------------------------------
-- The resolver's records: its cache and its local data
-- (specs/SPEC-resolver-cache-attribution.md).
--
-- The cache and the local data of the one resolver are active, and each has been
-- read successfully; resource_record_read holds that last poll.
-- ---------------------------------------------------------------------------
UPDATE provider SET is_active = true
WHERE kind IN ('resolver_cache', 'resolver_local_data') AND provider_key = 'unbound';

INSERT INTO resource_record_read (provider_id, read_at)
SELECT id, :now FROM provider
WHERE kind IN ('resolver_cache', 'resolver_local_data') AND provider_key = 'unbound';

-- The cache held the answer of one attributed flow in four: for those, the name the
-- client looked up answered with the flow's destination over the whole interval from
-- the lookup to the flow, so the flow is named by resolver_cache_answer. Half of them
-- reach it directly, an A or AAAA record of the looked-up name; the other half through
-- a CNAME to a name of their own. Every eligible flow so named is an outside
-- destination of a client, not this firewall and not a second leg, as the rule asks;
-- each record covers from thirty seconds before its lookup to thirty seconds after its
-- flow, which is no other flow's instant. Every name is synthesised and every address
-- is the seed's own.
CREATE TEMP TABLE cache_named (
    flow_id     INTEGER PRIMARY KEY,
    domain      TEXT NOT NULL,
    destination TEXT NOT NULL,
    looked_up_at INTEGER NOT NULL,
    observed_at INTEGER NOT NULL,
    chained     INTEGER NOT NULL
);

INSERT INTO cache_named (flow_id, domain, destination, looked_up_at, observed_at, chained)
SELECT f.id, r.domain, f.dst_address, r.looked_up_at, f.observed_at, (f.id / 12) % 2
FROM flow AS f
JOIN domain_attribution AS a ON a.flow_id = f.id
JOIN dns_resolution AS r ON r.id = a.dns_resolution_id
WHERE f.id % 12 = 11
  AND f.src_client_id IS NOT NULL
  AND f.dst_interface_id IS NULL
  AND NOT f.dst_is_this_firewall
  AND NOT f.src_is_this_firewall
  AND (f.pair_outcome IS NULL OR f.pair_outcome <> 'second_leg');

-- The address records. The id is derived from the flow's, so the attribution can name
-- it below without a search.
INSERT INTO resource_record_observation (id, provider_id, held_in, owner_name, rrtype, value,
                                         address, host_label, first_seen_at, last_seen_at,
                                         covered_from_at, covered_until_at)
SELECT 3000000000 + c.flow_id,
       (SELECT id FROM provider WHERE kind = 'resolver_cache' AND provider_key = 'unbound'),
       'cache',
       CASE WHEN c.chained = 1 THEN format('edge-%s.example-cdn.invalid', c.flow_id)
            ELSE lower(rtrim(c.domain, '.')) END,
       CASE WHEN strpos(c.destination, ':') > 0 THEN 'AAAA' ELSE 'A' END,
       c.destination, c.destination, NULL,
       c.looked_up_at - 20, c.observed_at + 10, c.looked_up_at - 30, c.observed_at + 30
FROM cache_named AS c;

-- The CNAME of the looked-up name, for the chained half.
INSERT INTO resource_record_observation (id, provider_id, held_in, owner_name, rrtype, value,
                                         address, host_label, first_seen_at, last_seen_at,
                                         covered_from_at, covered_until_at)
SELECT 4000000000 + c.flow_id,
       (SELECT id FROM provider WHERE kind = 'resolver_cache' AND provider_key = 'unbound'),
       'cache', lower(rtrim(c.domain, '.')), 'CNAME',
       format('edge-%s.example-cdn.invalid', c.flow_id), NULL, NULL,
       c.looked_up_at - 20, c.observed_at + 10, c.looked_up_at - 30, c.observed_at + 30
FROM cache_named AS c
WHERE c.chained = 1;

UPDATE domain_attribution
SET method = 'resolver_cache_answer',
    address_observation_id = 3000000000 + flow_id
WHERE flow_id IN (SELECT flow_id FROM cache_named);

DROP TABLE cache_named;

-- Records the cache held that no attributed flow names, in both families, so the
-- purge and the coverage read have unnamed rows too: one per external slot in a
-- hundred, each seen by two consecutive polls a minute apart.
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 40
)
INSERT INTO resource_record_observation (provider_id, held_in, owner_name, rrtype, value,
                                         address, host_label, first_seen_at, last_seen_at,
                                         covered_from_at, covered_until_at)
SELECT (SELECT id FROM provider WHERE kind = 'resolver_cache' AND provider_key = 'unbound'),
       'cache', format('unnamed-%s.example-cdn.invalid', n),
       CASE WHEN n % 2 = 0 THEN 'AAAA' ELSE 'A' END,
       CASE WHEN n % 2 = 0 THEN a.address_v6 ELSE a.address_v4 END,
       CASE WHEN n % 2 = 0 THEN a.address_v6 ELSE a.address_v4 END,
       NULL,
       :now - n * 86400, :now - n * 86400 + 60, :now - n * 86400 - 60, :now - n * 86400 + 360
FROM counter
JOIN synth_address AS a ON a.slot = 1000000 + 3500 + n;

-- RC-AC14's two branches, at every seed size (specs/SPEC-resolver-cache-closing.md,
-- scope 4). The purge removes a record whose coverage ended before the horizon, except
-- one a surviving attribution names.
--
-- The keep branch. A flow observed three seconds after the horizon, of the first flow's
-- shape -- so it survives the purge -- named by resolver_cache_answer through a cache
-- record whose coverage ended before the horizon. The rule never writes such a row: the
-- record it names covers the flow. It is planted, outside the live-validation window, so
-- that the purge's reference exclusion is what keeps the record; without it the
-- foreign key refuses the purge outright. The horizon is read from the setting, as the
-- purge reads it.
-- sql/schema-checks.sh (RC-FOLLOW-AC4) fails if any of these rows moves inside the
-- live-validation window.
INSERT INTO flow (id, log_digest, observed_at, ingested_at, interface_device,
                  interface_lookup_state, src_interface_id, dst_interface_id,
                  src_client_id, dst_client_id, src_address, dst_address,
                  src_port, dst_port, protocol, ip_version, action, direction,
                  log_reason, packet_bytes, rid, rule_id, rule_lookup_state, traffic_scope)
SELECT 2000000002, 'log-digest-kept-resolver-record', h.horizon + 3, h.horizon + 8, interface_device,
       interface_lookup_state, src_interface_id, dst_interface_id, src_client_id, dst_client_id,
       src_address, dst_address, src_port, dst_port, protocol, ip_version, action, direction,
       log_reason, packet_bytes, rid, rule_id, rule_lookup_state, traffic_scope
FROM flow
CROSS JOIN (SELECT :now - CAST(value AS BIGINT) AS horizon FROM setting
      WHERE key = 'retention_seconds') AS h
WHERE flow.id = 1;

INSERT INTO dns_resolution (id, lookup_key, client_address, client_id, domain,
                            resolver, action, answer_source, rcode, dnssec_status,
                            looked_up_at, ingested_at, interface_id, interface_lookup_state)
SELECT 2000000002, 'lookup-uuid-kept-resolver-record', src_address, src_client_id,
       'kept-record.example-zone.invalid', 'unbound', 'pass', 'Recursion', 'NOERROR',
       NULL, observed_at - 4, observed_at, src_interface_id,
       CASE WHEN src_interface_id IS NULL THEN 'not_found' ELSE 'resolved' END
FROM flow WHERE id = 2000000002;

INSERT INTO resource_record_observation (provider_id, held_in, owner_name, rrtype, value,
                                         address, host_label, first_seen_at, last_seen_at,
                                         covered_from_at, covered_until_at)
SELECT (SELECT id FROM provider WHERE kind = 'resolver_cache' AND provider_key = 'unbound'),
       'cache', 'kept-record.example-zone.invalid',
       CASE WHEN strpos(f.dst_address, ':') > 0 THEN 'AAAA' ELSE 'A' END,
       f.dst_address, f.dst_address, NULL,
       f.observed_at - 600, f.observed_at - 540, f.observed_at - 660, f.observed_at - 240
FROM flow AS f WHERE f.id = 2000000002;

INSERT INTO domain_attribution (flow_id, dns_resolution_id, site_name,
                                correlation_delay_seconds, attributed_at, method,
                                address_observation_id)
SELECT 2000000002, 2000000002, 'kept-record.example-zone.invalid', 4, f.observed_at,
       'resolver_cache_answer',
       (SELECT id FROM resource_record_observation WHERE owner_name = 'kept-record.example-zone.invalid')
FROM flow AS f WHERE f.id = 2000000002;

-- The purge branch. Records the cache held that nothing names, whose coverage ended
-- before the horizon, one per family: the purge removes them at every seed size,
-- including the smaller ones whose flows all lie after the horizon.
WITH RECURSIVE counter (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 2
)
INSERT INTO resource_record_observation (provider_id, held_in, owner_name, rrtype, value,
                                         address, host_label, first_seen_at, last_seen_at,
                                         covered_from_at, covered_until_at)
SELECT (SELECT id FROM provider WHERE kind = 'resolver_cache' AND provider_key = 'unbound'),
       'cache', format('expired-unnamed-%s.example-cdn.invalid', n),
       CASE WHEN n % 2 = 0 THEN 'AAAA' ELSE 'A' END,
       CASE WHEN n % 2 = 0 THEN a.address_v6 ELSE a.address_v4 END,
       CASE WHEN n % 2 = 0 THEN a.address_v6 ELSE a.address_v4 END,
       NULL,
       h.horizon - 3600 * n, h.horizon - 3600 * n + 60, h.horizon - 3600 * n - 60,
       h.horizon - 3600 * n + 360
FROM counter
JOIN synth_address AS a ON a.slot = 1000000 + 3560 + n
CROSS JOIN (SELECT :now - CAST(value AS BIGINT) AS horizon FROM setting
      WHERE key = 'retention_seconds') AS h;

-- The local data: a host override for a few clients, in both families -- an A or AAAA
-- record of the host name, and the PTR record that maps the address back, its owner the
-- reverse name of the address (RFC 1035, section 3.5; RFC 3596, section 2.5) computed
-- from the slot the address was synthesised from. Each covers the half hour around the
-- lookup that names its host below.
WITH RECURSIVE counter (n) AS (
    SELECT 13
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 16
),
-- The clients are chosen so both families appear whatever the counts: a client's
-- family follows its position within its interface (see the clients above), and the
-- first client of every interface is an IPv6 one, the next an IPv4 one.
host AS (
    SELECT n, c.id AS slot, c.last_address AS address,
           format('local-host-%s', n) AS label,
           :now - (n * 457) - 7 AS at
    FROM counter
    JOIN client AS c ON c.id = CASE WHEN n % 2 = 1 THEN n - 12 ELSE n - 12 + :interfaces END
)
INSERT INTO resource_record_observation (provider_id, held_in, owner_name, rrtype, value,
                                         address, host_label, first_seen_at, last_seen_at,
                                         covered_from_at, covered_until_at)
SELECT (SELECT id FROM provider WHERE kind = 'resolver_local_data' AND provider_key = 'unbound'),
       'local_data', format('%s.example-zone.invalid', h.label),
       CASE WHEN strpos(h.address, ':') > 0 THEN 'AAAA' ELSE 'A' END,
       h.address, h.address, h.label, h.at - 600, h.at + 600, h.at - 900, h.at + 900
FROM host AS h
UNION ALL
SELECT (SELECT id FROM provider WHERE kind = 'resolver_local_data' AND provider_key = 'unbound'),
       'local_data',
       CASE WHEN strpos(h.address, ':') > 0
            THEN concat_ws('.',
                        to_hex((h.slot % 65536) % 16), to_hex(((h.slot % 65536) / 16) % 16),
                        to_hex(((h.slot % 65536) / 256) % 16), to_hex(((h.slot % 65536) / 4096) % 16),
                        to_hex(((h.slot * 29) % 65536) % 16), to_hex((((h.slot * 29) % 65536) / 16) % 16),
                        to_hex((((h.slot * 29) % 65536) / 256) % 16), to_hex((((h.slot * 29) % 65536) / 4096) % 16),
                        to_hex(((h.slot * 23) % 65536) % 16), to_hex((((h.slot * 23) % 65536) / 16) % 16),
                        to_hex((((h.slot * 23) % 65536) / 256) % 16), to_hex((((h.slot * 23) % 65536) / 4096) % 16),
                        to_hex(((h.slot * 19) % 65536) % 16), to_hex((((h.slot * 19) % 65536) / 16) % 16),
                        to_hex((((h.slot * 19) % 65536) / 256) % 16), to_hex((((h.slot * 19) % 65536) / 4096) % 16),
                        to_hex(((h.slot * 17) % 65536) % 16), to_hex((((h.slot * 17) % 65536) / 16) % 16),
                        to_hex((((h.slot * 17) % 65536) / 256) % 16), to_hex((((h.slot * 17) % 65536) / 4096) % 16),
                        to_hex(((h.slot * 13) % 65536) % 16), to_hex((((h.slot * 13) % 65536) / 16) % 16),
                        to_hex((((h.slot * 13) % 65536) / 256) % 16), to_hex((((h.slot * 13) % 65536) / 4096) % 16),
                        to_hex(((h.slot * 11) % 65536) % 16), to_hex((((h.slot * 11) % 65536) / 16) % 16),
                        to_hex((((h.slot * 11) % 65536) / 256) % 16), to_hex((((h.slot * 11) % 65536) / 4096) % 16),
                        to_hex(((h.slot * 7) % 65536) % 16), to_hex((((h.slot * 7) % 65536) / 16) % 16),
                        to_hex((((h.slot * 7) % 65536) / 256) % 16), to_hex((((h.slot * 7) % 65536) / 4096) % 16),
                        'ip6.arpa')
            ELSE format('%s.%s.%s.%s.in-addr.arpa', h.slot % 256, (h.slot / 256) % 256,
                        (h.slot / 65536) % 256, (h.slot / 16777216) % 256) END,
       'PTR', format('%s.example-zone.invalid', h.label), h.address, h.label,
       h.at - 600, h.at + 600, h.at - 900, h.at + 900
FROM host AS h;

-- The lookups whose logged host name no lease named and the local data did, at their
-- instant, with one address: their client is that address. And one more of the same
-- host, at an instant the local data held no record of it, which stays unknown. Their
-- answers are not eligible to name a flow -- the query report's Local source -- so they
-- add no candidate to any flow's attribution.
WITH RECURSIVE counter (n) AS (
    SELECT 13
    UNION ALL
    SELECT n + 1 FROM counter WHERE n < 17
)
INSERT INTO dns_resolution (id, lookup_key, client_address, client_hostname, client_resolution,
                            client_id, domain, resolver, action, answer_source, rcode,
                            dnssec_status, looked_up_at, ingested_at, interface_id,
                            interface_lookup_state)
SELECT
    1200000000 + n,
    format('hostname-lookup-uuid-%s', n),
    CASE WHEN n < 17 THEN c.last_address ELSE 'local-host-13.example-zone.invalid' END,
    CASE WHEN n < 17 THEN format('local-host-%s.example-zone.invalid', n)
         ELSE 'local-host-13.example-zone.invalid' END,
    CASE WHEN n < 17 THEN 'local_data_hostname' ELSE 'unknown_hostname' END,
    CASE WHEN n < 17 THEN c.id END,
    format('hostname-name-%s.example-zone-%s.invalid', n, n % 3),
    'unbound',
    'pass',
    'Local',
    'NOERROR',
    NULL,
    CASE WHEN n < 17 THEN :now - (n * 457) - 7 ELSE :now - (13 * 457) - 7 + 3600 END,
    CASE WHEN n < 17 THEN :now - (n * 457) - 5 ELSE :now - (13 * 457) - 5 + 3600 END,
    CASE WHEN n < 17 THEN c.interface_id END,
    CASE WHEN n < 17 THEN 'resolved' ELSE 'not_found' END
FROM counter
JOIN client AS c ON c.id = CASE WHEN n % 2 = 1 THEN n - 12 ELSE n - 12 + :interfaces END;

-- ---------------------------------------------------------------------------
-- The six aggregate families, four calendar periods each.
--
-- They are computed from opnview's own stored flows, exactly as the refresh in
-- internal/store/derive.sql computes them, not from any Insight column:
-- per-address-pair volume on the firewall exists only at daily resolution and
-- only for 62 days, and per-source totals at 300 s resolution are kept one hour
-- (survey, data source 3), so every period can only come from opnview's own
-- history. computed_at is the freshness stamp.
--
-- The periods are calendar slots aligned to UTC: the hour, the day, the ISO week
-- starting Monday, and the calendar month. The slot of every flow in every period
-- is written once, into a TEMP table, so the twenty-four statements below share one
-- definition of a slot rather than twenty-four copies of it. 1970-01-01 was a
-- Thursday, so the day number plus three, modulo seven, counts days since Monday.
--
-- Every family carries the allowed / blocked byte split, the direction and peer
-- come from classified_flow, and a flow belongs to its INSIDE client.
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE seed_flow_slot (
    flow_id         INTEGER NOT NULL,
    period          TEXT NOT NULL,
    period_start_at INTEGER NOT NULL,
    period_end_at   INTEGER NOT NULL
);

INSERT INTO seed_flow_slot (flow_id, period, period_start_at, period_end_at)
SELECT id, '1h', (observed_at / 3600) * 3600, (observed_at / 3600) * 3600 + 3600
FROM flow
UNION ALL
SELECT id, '24h', (observed_at / 86400) * 86400, (observed_at / 86400) * 86400 + 86400
FROM flow
UNION ALL
SELECT id, '7d', week_start_at, week_start_at + 604800
FROM (SELECT id,
             (observed_at / 86400) * 86400 - (((observed_at / 86400) + 3) % 7) * 86400
                 AS week_start_at
      FROM flow)
UNION ALL
SELECT id, '30d',
       month_start_at(observed_at),
       next_month_start_at(observed_at)
FROM flow;

-- Every aggregate row below is given its id here, the largest in use plus its row
-- number, which is the number the schema's assign_id trigger would give it: the
-- trigger takes an advisory lock and reads max(id) once per row, which at the
-- million-row seed is most of the seed's time, and it does nothing to a row that
-- arrives with an id.
INSERT INTO volume_aggregate_1h (id, period_start_at, period_end_at, src_interface_id,
    dst_interface_id, peer_address, traffic_scope, traffic_direction, exit_leg_device, bytes,
    allowed_bytes, blocked_bytes, unknown_bytes, allowed_connections, blocked_connections, unknown_connections, computed_at)
SELECT (SELECT coalesce(max(id), 0) FROM volume_aggregate_1h) + row_number() OVER (), s.period_start_at, s.period_end_at, f.src_interface_id, f.dst_interface_id,
       f.peer_address, f.traffic_scope, f.traffic_direction, f.exit_leg_device,
       sum(f.packet_bytes),
       sum(CASE WHEN f.action = 'pass' THEN f.packet_bytes ELSE 0 END),
       sum(CASE WHEN f.action IN ('block', 'reject') THEN f.packet_bytes ELSE 0 END),
       sum(CASE WHEN f.action = 'unknown' THEN f.packet_bytes ELSE 0 END),
       sum(CASE WHEN f.action = 'pass' THEN 1 ELSE 0 END),
       sum(CASE WHEN f.action IN ('block', 'reject') THEN 1 ELSE 0 END),
       sum(CASE WHEN f.action = 'unknown' THEN 1 ELSE 0 END),
       :now
FROM seed_flow_slot AS s
JOIN classified_flow AS f ON f.id = s.flow_id
WHERE s.period = '1h'
GROUP BY s.period_start_at, s.period_end_at, f.src_interface_id, f.dst_interface_id,
         f.peer_address, f.traffic_scope, f.traffic_direction, f.exit_leg_device;

INSERT INTO volume_aggregate_24h (id, period_start_at, period_end_at, src_interface_id,
    dst_interface_id, peer_address, traffic_scope, traffic_direction, exit_leg_device, bytes,
    allowed_bytes, blocked_bytes, unknown_bytes, allowed_connections, blocked_connections, unknown_connections, computed_at)
SELECT (SELECT coalesce(max(id), 0) FROM volume_aggregate_24h) + row_number() OVER (), s.period_start_at, s.period_end_at, f.src_interface_id, f.dst_interface_id,
       f.peer_address, f.traffic_scope, f.traffic_direction, f.exit_leg_device,
       sum(f.packet_bytes),
       sum(CASE WHEN f.action = 'pass' THEN f.packet_bytes ELSE 0 END),
       sum(CASE WHEN f.action IN ('block', 'reject') THEN f.packet_bytes ELSE 0 END),
       sum(CASE WHEN f.action = 'unknown' THEN f.packet_bytes ELSE 0 END),
       sum(CASE WHEN f.action = 'pass' THEN 1 ELSE 0 END),
       sum(CASE WHEN f.action IN ('block', 'reject') THEN 1 ELSE 0 END),
       sum(CASE WHEN f.action = 'unknown' THEN 1 ELSE 0 END),
       :now
FROM seed_flow_slot AS s
JOIN classified_flow AS f ON f.id = s.flow_id
WHERE s.period = '24h'
GROUP BY s.period_start_at, s.period_end_at, f.src_interface_id, f.dst_interface_id,
         f.peer_address, f.traffic_scope, f.traffic_direction, f.exit_leg_device;

